    if type(list) == "table" and #list > 0 then
        W.spots, W.spotsAt, W.sector_ = list, os.clock(), sec
        W.done = {}
    else
        W.spotsAt = os.clock() - 30
    end
end
function W.standAt(p)
    local rp = M.worldRP()
    local h = Workspace:Raycast(p + Vector3.new(0, 7, 0), Vector3.new(0, -14, 0), rp)
    if h and h.Distance > 0.5 then return h.Position + Vector3.new(0, 3.1, 0) end
    local top = M.surface(p)
    if top then return top + Vector3.new(0, 3.1, 0) end
    return nil
end
function W.next()
    W.refresh()
    local r = M.root()
    if not r or #W.spots == 0 then return nil end
    local best, bd
    local now = os.clock()
    for i, p in ipairs(W.spots) do
        if not W.done[i] or now - W.done[i] > 150 then
            local d = (p - r.Position).Magnitude
            if not best or d < bd then best, bd = i, d end
        end
    end
    if not best then W.done = {} return nil end
    return best
end
function W.step()
    if not (on("f_flatten") or S.foot()) or not M.ready() or S.busy then return end
    local r = M.root()
    if not r then return end
    if r.Position.Y < M.floorY() - 25 and W.cur then
        local p = W.standAt(W.spots[W.cur])
        if p then M.go(p) end
        return
    end
    local dry = W.curAt and os.clock() - W.curAt > 3 and os.clock() - math.max(V.lastOwn or 0, W.curAt) > 2.5
    local stuck = (G.idleSince and os.clock() - G.idleSince > 1.2) or dry
    if not W.cur or stuck or os.clock() - W.curAt > tonumber(val("f_dwell", 25)) then
        if W.cur then W.done[W.cur] = os.clock() end
        local i = W.next()
        if not i then return end
        local p = W.standAt(W.spots[i])
        if not p then W.done[i] = os.clock() return end
        W.cur, W.curAt = i, os.clock()
        G.idleSince = nil
        G.scan = nil
        M.go(p)
        S.task = __T["Flattening"]
    end
end
