local T = { black = {}, crateSpin = false }
function T.reach(pos, isDone, label)
    local r = M.root()
    if not r then return false end
    S.busy, S.task = true, label
    local stand
    local ok = pcall(function()
        local top = M.surface(pos)
        if not top then return end
        stand = top + Vector3.new(0, 3.1, 0)
        if top.Y - pos.Y < 10 then
            local off = Vector3.new(6, 0, 0)
            local side = M.surface(pos + off)
            if side and math.abs(side.Y - pos.Y) < 12 then stand = side + Vector3.new(0, 3.1, 0) end
        end
        M.go(stand)
        task.wait(0.25)
        local t0, lastY, lastMove = os.clock(), M.root().Position.Y, os.clock()
        while RUNNING and os.clock() - t0 < 30 and not isDone() do
            r = M.root()
            if not r or not M.alive() then break end
            local dy = r.Position.Y - pos.Y
            if dy > 9 then
                local h = Workspace:Raycast(r.Position, Vector3.new(0, -12, 0), M.terrainRP)
                G.force = h and h.Position or (r.Position - Vector3.new(0, 5, 0))
            else
                G.force = pos
            end
            if r.Position.Y < lastY - 1 then lastY, lastMove = r.Position.Y, os.clock() end
            if dy > 9 and os.clock() - lastMove > 5 then break end
            task.wait(0.15)
        end
    end)
    G.force = nil
    local done = ok and isDone()
    if stand and not T.keepDown then M.go(stand) end
    S.busy = false
    return done
end
function T.gems()
