        if not T.black[g] then list[#list + 1] = { g = g, d = (g:GetPivot().Position - r.Position).Magnitude, s = g:GetAttribute("Surface") == true } end
    end
    table.sort(list, function(a, b) if a.s ~= b.s then return a.s end return a.d < b.d end)
    local e = list[1]
