    local g = e.g
    local before = M.gemsN()
    local got = T.reach(g:GetPivot().Position, function() return g.Parent == nil end, __T["Gem hunting"])
    if got then S.gems += math.max(0, M.gemsN() - before) else T.black[g] = true end
