U.TIER = { DrillMachine = 1, Bulldozer = 2, GreatExcavator = 3 }
function U.nextTool()
    local top = 0
    for id, t in pairs(U.TIER) do if M.owned(id) and t > top then top = t end end
    for _, id in ipairs(U.TOOLS) do
        if not U.TIER[id] and picked("u_tools", id) and not M.owned(id) then return id, M.toolPrice(id) end
    end
    if not on("v_auto") then return nil end
    local cash, best, cheap = M.spendable(), nil, nil
    for _, id in ipairs(U.TOOLS) do
        local t = U.TIER[id]
        if t and t > top and picked("u_tools", id) and not M.owned(id) then
            local p = M.toolPrice(id)
            if p <= cash and (not best or t > U.TIER[best]) then best = id end
            if not cheap or p < M.toolPrice(cheap) then cheap = id end
        end
    end
    local id = best or cheap
    if id then return id, M.toolPrice(id) end
end
function U.buyTools()
    local id, price = U.nextTool()
