    local ok, msg = M.call("BuyTool", id)
    LOG("buy tool", id, ok, msg)
    if ok then S.bought += 1 notify(__T["Bought "] .. ((D.Tool.Tools[id] or {}).DisplayName or id)) return true end
    U.fail["T" .. id] = os.clock()
