end
function U.upgradeList()
    local d = M.data()
    local lv = type(d.Upgrades) == "table" and d.Upgrades or {}
    local list = {}
    for _, id in ipairs(G.DIG) do
        if M.owned(id) then
            for _, st in ipairs(U.STATS) do
                if picked("u_stats", st) then
                    local key = id .. st
                    local def = D.Upg.Upgrades and D.Upg.Upgrades[key]
                    if def then
                        local l = tonumber(lv[key]) or 0
                        local cost = D.Upg.Cost and gcall(D.Upg.Cost, key, l)
                        if cost then list[#list + 1] = { key = key, cost = cost, w = cost * (st == "Power" and 0.6 or st == "Speed" and 0.8 or 1) } end
                    end
                end
            end
        end
    end
    table.sort(list, function(a, b) return a.w < b.w end)
    return list
