function U.buyUpgrades()
    local budget = M.spendable()
    if on("u_toolsfirst") and on("u_tool") then
        local id, price = U.nextTool()
        if id and price < math.huge then budget = math.min(budget, math.max(0, price * 0.1)) end
    end
    for _, e in ipairs(U.upgradeList()) do
        if e.cost <= budget and U.canTry(e.key) then
            local ok, msg = M.call("BuyUpgrade", e.key)
            LOG("upgrade", e.key, ok, msg)
            if ok then S.bought += 1 return true end
            U.fail[e.key] = os.clock()
        end
    end
    return false
end
