                    pcall(function()
                        local pp = M.promptPos(pr)
                        if pp then M.go(pp + Vector3.new(0, 3, 6)) task.wait(0.35) M.prompt(pr) task.wait(0.8) end
                    end)
                    if back then M.go(back) end
                    S.busy = false
