VH.ghost = setmetatable({}, { __mode = "k" })
function VH.clearWalls(mdl, root)
    local keep = {}
    local inv = Workspace:FindFirstChild("GameInvisibleWalls")
    local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    if look.Magnitude < 0.01 then return end
    look = look.Unit
    local cf, size = mdl:GetBoundingBox()
    local center = cf.Position + look * (size.Z * 0.35)
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = { mdl, lp.Character, Workspace.Terrain, inv }
    local box = Vector3.new(math.max(size.X, size.Z) + 10, size.Y + 6, math.max(size.X, size.Z) + 10)
    local bottom = cf.Position.Y - size.Y / 2 + 2.5
    for _, p in ipairs(Workspace:GetPartBoundsInBox(CFrame.new(center), box, op)) do
        if p.CanCollide and p.Name ~= "Level0" and (p.Position.Y + p.Size.Y / 2) > bottom and not p:IsDescendantOf(Workspace:FindFirstChild("HeavyVehicles") or mdl) then
            VH.ghost[p] = os.clock()
            p.CanCollide = false
        end
    end
    for p, t in pairs(VH.ghost) do
        if os.clock() - t > 4 and p.Parent and (p.Position - root.Position).Magnitude > 70 then
            p.CanCollide = true
            VH.ghost[p] = nil
        end
    end
end
function VH.restoreWalls() for p in pairs(VH.ghost) do pcall(function() p.CanCollide = true end) VH.ghost[p] = nil end end
