function VH.inMountain(p)
    local fo = Workspace:FindFirstChild("MountainSections")
    if not fo then return true end
    if not VH.allParts or os.clock() - (VH.allAt or 0) > 60 then
        VH.allAt, VH.allParts = os.clock(), {}
        for _, c in ipairs(fo:GetChildren()) do if c:IsA("BasePart") and c.Name:match("^Section%d") then VH.allParts[#VH.allParts + 1] = c end end
    end
    for _, c in ipairs(VH.allParts) do
        local rel = c.CFrame:PointToObjectSpace(p)
        if math.abs(rel.X) < c.Size.X / 2 + 10 and math.abs(rel.Z) < c.Size.Z / 2 + 10 then return true end
    end
    return #VH.allParts == 0
end
function VH.inSection(p)
    local fo = Workspace:FindFirstChild("MountainSections")
    local cur = fo and fo:GetAttribute("Current")
    if not cur then return true end
    if VH.secKey ~= cur or not VH.secParts then
        VH.secKey, VH.secParts = cur, {}
        for _, c in ipairs(fo:GetChildren()) do if c:IsA("BasePart") and c.Name == "Section" .. tostring(cur) then VH.secParts[#VH.secParts + 1] = c end end
    end
    for _, c in ipairs(VH.secParts) do
        local rel = c.CFrame:PointToObjectSpace(p)
        if math.abs(rel.X) < c.Size.X / 2 + 15 and math.abs(rel.Z) < c.Size.Z / 2 + 15 then return true end
    end
    return #VH.secParts == 0
end
function VH.origin(mdl, root)
