function VH.rockAt(origin, dir, range)
    local h = Workspace:Raycast(origin, dir * range, M.terrainRP)
    if h and h.Material ~= Enum.Material.Water and VH.inMountain(h.Position) and (not on("v_section") or VH.inSection(h.Position)) then return h end
    return nil
end
function VH.groundAhead(root, dir, dist)
    local p = root.Position + dir * dist
    local h = Workspace:Raycast(Vector3.new(p.X, root.Position.Y + 12, p.Z), Vector3.new(0, -70, 0), M.worldRP())
    return h ~= nil
end
function VH.ground(mdl, root, range)
    local origin = VH.origin(mdl, root)
    local cur = VH.heading or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    if cur.Magnitude < 0.01 then cur = Vector3.new(0, 0, -1) end
    cur = cur.Unit
    local fwd = math.deg(math.atan2(cur.X, cur.Z))
    local now = os.clock()
    local best, bc
    for deg = 0, 350, 10 do
        local r = math.rad(deg)
        local dir = Vector3.new(math.sin(r), 0, math.cos(r))
        local h = VH.rockAt(origin, dir, range or 220)
        if h and VH.groundAhead(root, dir, 30) then
            local diff = math.abs((deg - fwd + 540) % 360 - 180)
            local cost = h.Distance + diff * 3
            if (VH.bad[math.floor((deg + 15) / 30) % 12] or 0) > now then cost = cost + 600 end
            if not best or cost < bc then best, bc = dir, cost end
        end
    end
    return best
end
