track(RunService.Heartbeat:Connect(function(dt)
    if not VH.fmode or not VH.fcur then return end
    local root = VH.rootOf(VH.last or "GreatExcavator")
    if not root then return end
    local tgt = VH.ft and VH.ft.pos or VH.fcur
    local cur = VH.fcur
    local flat = Vector3.new(tgt.X - cur.X, 0, tgt.Z - cur.Z)
    local hs = (VH.hspeed or (on("v_boost") and 18 or 14)) * dt
    local step = flat.Magnitude > 0.05 and flat.Unit * math.min(hs, flat.Magnitude) or Vector3.zero
    local dy = math.clamp(tgt.Y - cur.Y, -10 * dt, 10 * dt)
    cur = Vector3.new(cur.X + step.X, cur.Y + dy, cur.Z + step.Z)
    VH.fcur = cur
    local want = VH.ft and VH.ft.look or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    if want.Magnitude < 0.01 then want = Vector3.new(0, 0, -1) end
    want = want.Unit
    local look = VH.flook or want
    local ang = math.acos(math.clamp(look:Dot(want), -1, 1))
    local maxT = math.rad(120) * dt
    if ang > maxT then
        local axis = look:Cross(want)
        local s = axis.Y >= 0 and 1 or -1
        look = (CFrame.Angles(0, s * maxT, 0) * CFrame.new(Vector3.zero, look)).LookVector
    else
        look = want
    end
    VH.flook = Vector3.new(look.X, 0, look.Z).Unit
    if ang > math.rad(45) then cur = VH.fcur - Vector3.new(step.X, 0, step.Z) VH.fcur = cur end
    local amp = VH.bobAmp or 12
    local bob = amp > 0 and Vector3.new(0, math.sin(os.clock() * (VH.bobRate or 2.5)) * amp, 0) or Vector3.zero
    root.CFrame = CFrame.lookAt(cur + bob, cur + bob + VH.flook)
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
end))
VH.fbad = {}
function VH.cell(p) return math.floor(p.X / 16) .. ":" .. math.floor(p.Y / 22) .. ":" .. math.floor(p.Z / 16) end
VH.fail = {}
function VH.failHere(p)
    VH.fail[#VH.fail + 1] = { p = p, t = os.clock() + 300 }
