VH.AIR = { [Enum.Material.Air] = true, [Enum.Material.Water] = true }
function VH.wheel()
    local mdl = VH.model(VH.last or "GreatExcavator")
    local w = mdl and mdl:GetAttribute("WheelCenter")
    if typeof(w) == "Vector3" then return math.abs(w.Z), w.Y end
    return 12, 0
end
function VH.voxTarget(cur)
    local r = 64
    local reg = Region3.new(cur - Vector3.new(r, r, r), cur + Vector3.new(r, r, r)):ExpandToGrid(4)
    local ok, mats, occ = pcall(function() return Workspace.Terrain:ReadVoxels(reg, 4) end)
    if not ok or not mats then return nil end
    local sz = mats.Size
    local corner = reg.CFrame.Position - reg.Size / 2
    local fy = M.floorY() + 2
    local best, bd
    for x = 1, sz.X do
        local mx, ox = mats[x], occ[x]
        for y = 1, sz.Y do
            local wy = corner.Y + (y - 0.5) * 4
            if wy > fy then
                local my, oy = mx[y], ox[y]
                for z = 1, sz.Z do
                    if oy[z] > 0.5 and not VH.AIR[my[z]] then
                        local p = corner + Vector3.new((x - 0.5) * 4, (y - 0.5) * 4, (z - 0.5) * 4)
                        local dd = (p - cur).Magnitude
                        if (not best or dd < bd) and dd > 4 then
                            if VH.inMountain(p) and (not on("v_section") or VH.inSection(p)) and not VH.nearFail(p) then best, bd = p, dd end
                        end
                    end
                end
            end
        end
    end
    if not best then return nil end
    local flat = Vector3.new(best.X - cur.X, 0, best.Z - cur.Z)
    local dir = flat.Magnitude > 1 and flat.Unit or (VH.flook or Vector3.new(0, 0, -1))
    local wz, wy = VH.wheel()
    return { pos = Vector3.new(best.X, best.Y - wy, best.Z) - dir * (wz - 6), look = dir, y = best.Y, vox = true }
end
function VH.floatTarget(root)
    local cur0 = VH.fcur or root.Position
    local wz = VH.wheel()
    local lk = VH.flook or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z).Unit
    local v = VH.voxTarget(cur0 + lk * wz)
    if v then return v end
    local fy = M.floorY()
    local cur = VH.fcur or root.Position
    local best, bc
    for hh = 8, 338, 22 do
        local origin = Vector3.new(cur.X, fy + hh, cur.Z)
        for deg = 0, 350, 10 do
            local r = math.rad(deg)
            local dir = Vector3.new(math.sin(r), 0, math.cos(r))
            local h = VH.rockAt(origin, dir, 1500)
            if h and (VH.fbad[VH.cell(h.Position)] or 0) < os.clock() and not VH.nearFail(h.Position) and not VH.nearFail(h.Position - dir * 12) then
                local cost = h.Distance + math.abs(origin.Y - 8 - cur.Y) * 1.5
                local lk = VH.flook or dir
                local turn = math.deg(math.acos(math.clamp(lk:Dot(dir), -1, 1)))
                cost = cost + turn * 0.8
                local wz, wy = VH.wheel()
                if not best or cost < bc then best, bc = { pos = Vector3.new(h.Position.X, origin.Y - wy, h.Position.Z) - dir * (wz - 6), look = dir, y = origin.Y }, cost end
            end
        end
    end
    return best
end
function VH.floatStep(k, seat, root)
    local now = os.clock()
    VH.set(seat, 0, 0)
    local cutting = now - VH.lastStone < 2.5
    local ft = VH.ft
    if ft then
        local d = Vector3.new(ft.pos.X - VH.fcur.X, 0, ft.pos.Z - VH.fcur.Z).Magnitude + math.abs(ft.pos.Y - VH.fcur.Y)
        if d < 4 then
            if not VH.ftArrive then VH.ftArrive, VH.ftN0 = now, VH.stoneN or 0 end
            local got = (VH.stoneN or 0) - (VH.ftN0 or 0)
            if now - VH.ftArrive >= 5 then
                if got < 800 then
                    VH.markBad(ft.pos + ft.look * VH.wheel(), 300)
                    VH.failHere(VH.fcur or ft.pos)
                    VH.failHere(ft.pos + ft.look * VH.wheel())
                    VH.ft = nil
                else
                    VH.ftArrive, VH.ftN0 = now, VH.stoneN or 0
                end
            end
            if VH.ft and cutting then ft.pos = ft.pos + ft.look * (VH.pushRate or 30) * 0.05 end
        else
            VH.ftArrive = nil
        end
        if VH.ft and now - math.max(VH.ftAt, VH.fprog or 0) > 5 and not VH.ftArrive then VH.markBad(ft.pos + ft.look * VH.wheel(), 300) VH.failHere(ft.pos) VH.ft = nil end
    end
    if not VH.ft then
        VH.ftArrive, VH.ftGot, VH.fbest = nil, false, nil
        VH.ft, VH.ftAt = VH.floatTarget(root), now
        VH.fprog = now
        if not VH.ft then
            LOG("no rock left anywhere, digging on foot")
            VH.exitFloat()
            S.footUntil = now + 60
            VH.exit()
            return
        end
        VH.turns = (VH.turns or 0) + 1
    end
end
function VH.drive(k)
    local mdl = VH.model(k)
    local seat = mdl and mdl:FindFirstChild("DriverSeat")
    local root = mdl and (mdl.PrimaryPart or seat)
    if not (seat and root) then return end
    if root.Position.Y < M.floorY() - 30 then
        LOG("vehicle sank, fresh spawn")
        VH.fresh = true
        VH.exit()
        return
    end
    if mdl:GetAttribute("WheelOn") ~= true and os.clock() - (VH.wheelAt or 0) > 2 then VH.wheelAt = os.clock() M.fire("HeavyWheel", { On = true }) end
    if os.clock() - (VH.wallAt or 0) > 0.2 then VH.wallAt = os.clock() pcall(VH.clearWalls, mdl, root) end
    if on("v_float") and not VH.fmode then VH.enterFloat(root) end
    if VH.fmode then
        if VH.ft and VH.fcur then
            local dd = (VH.ft.pos - VH.fcur).Magnitude
            if not VH.fbest or dd < VH.fbest - 3 then VH.fbest, VH.fprog = dd, os.clock() end
        end
        local n = VH.stoneN or 0
        if not VH.goodAt or n - (VH.goodN or 0) >= 1000 then VH.goodAt, VH.goodN = os.clock(), n end
        local live = math.max(VH.goodAt, VH.fprog or 0, VH.seatAt or 0)
        if os.clock() - live > 45 then
            LOG("float stuck, fresh spawn")
            VH.exitFloat()
            VH.fresh = true
            VH.exit()
            return
        end
        VH.floatStep(k, seat, root)
        return
    end
    local now = os.clock()
    local origin = VH.origin(mdl, root)
    local cutting = now - VH.lastStone < 2.5
    if VH.heading then
        local ahead = VH.rockAt(origin, VH.heading, 70)
            or VH.rockAt(origin, (CFrame.Angles(0, math.rad(20), 0) * CFrame.new(Vector3.zero, VH.heading)).LookVector, 60)
            or VH.rockAt(origin, (CFrame.Angles(0, math.rad(-20), 0) * CFrame.new(Vector3.zero, VH.heading)).LookVector, 60)
        if not ahead and not cutting and now - (VH.headAt or 0) > 2.5 then VH.heading = nil end
    end
    if not VH.heading then
        local dir = VH.ground(mdl, root) or VH.ground(mdl, root, 700)
        if dir then VH.heading, VH.headAt = dir, now VH.turns = (VH.turns or 0) + 1 end
    end
    if not VH.heading then
        if on("v_float") and now - VH.lastStone > 3 then
            VH.enterFloat(root)
            return
        end
        if now - VH.lastStone > 8 and now - (VH.seatAt or 0) > 8 then
            LOG("no ground rock left, digging on foot")
            S.footUntil = now + 60
            VH.exit()
        else
            VH.set(seat, 0, 0)
        end
        return
    end
    if now - VH.lastStone > 40 and now - (VH.seatAt or 0) > 40 then
        LOG("vehicle stuck, fresh spawn")
        VH.fresh = true
        VH.heading = nil
        VH.exit()
        return
    end
    local hd = VH.heading
    local lk = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    if lk.Magnitude > 0.01 and not VH.groundAhead(root, lk.Unit, 28) then
        LOG("edge ahead, backing off")
        VH.edges = (VH.edges or 0) + 1
        local yaw = math.deg(math.atan2(lk.X, lk.Z))
        VH.bad[math.floor(((yaw % 360) + 15) / 30) % 12] = now + 60
        VH.set(seat, -1, 0)
        local t0 = os.clock()
        while os.clock() - t0 < 1.2 do task.wait() end
        VH.set(seat, 0, 0)
        VH.heading = nil
        return
    end
    local look = root.CFrame.LookVector
    local a = math.atan2(look.X * hd.Z - look.Z * hd.X, look.X * hd.X + look.Z * hd.Z)
    local pos = root.Position
    if not VH.lastPos or now - (VH.lastPosAt or 0) > 1 then
        local moved = VH.lastPos and Vector3.new(pos.X - VH.lastPos.X, 0, pos.Z - VH.lastPos.Z).Magnitude or 99
        VH.lastPos, VH.lastPosAt = pos, now
        if moved > 2 then VH.tAt = now end
    end
    if cutting then VH.tAt = now end
    if now - VH.tAt > 5 then
        VH.stalls = (VH.stalls or 0) + 1
        local yaw = math.deg(math.atan2(hd.X, hd.Z))
        VH.bad[math.floor(((yaw % 360) + 15) / 30) % 12] = now + 25
        VH.set(seat, -1, 0)
        local t0 = os.clock()
        while os.clock() - t0 < 1.5 do task.wait() end
        VH.set(seat, 0, 0)
        VH.heading, VH.tAt = nil, os.clock()
        return
    end
    VH.set(seat, math.abs(a) > 1.2 and 0.3 or 1, math.clamp(a * 1.5, -1, 1))
end
