local E = { hl = setmetatable({}, { __mode = "k" }) }
function E.mark(m, col)
    if E.hl[m] and E.hl[m].Parent then return end
    local h = Instance.new("Highlight")
    h.FillTransparency, h.OutlineTransparency = 0.6, 0
    h.FillColor, h.OutlineColor = col, col
    h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    h.Adornee = m
    h.Parent = m
    E.hl[m] = h
end
function E.clear() for m, h in pairs(E.hl) do pcall(function() h:Destroy() end) E.hl[m] = nil end end
onClean(E.clear)
