    local groups = {
        { __T["Farm"], { __T["+ Auto vehicle dig"], __T["+ Flying digger"], __T["+ Faster driving + turning"], __T["+ Stay in section"], __T["+ Edge guard"], __T["+ Max speed dig"], __T["+ Instant vacuum anywhere"], __T["+ Auto flatten"], __T["+ Rich veins first"], __T["+ Auto gems"], __T["+ Auto lucky crates"], __T["+ Auto TNT barrels"], __T["+ Auto taco rain"], __T["+ Treasure ESP"] } },
        { __T["Shop"], { __T["+ Auto buy tools"], __T["+ Auto upgrades"], __T["+ Auto hangars"], __T["+ Auto drill upgrades"], __T["+ Auto gem upgrades"], __T["+ Auto classes"], __T["+ Keep cash"] } },
        { "Lobby", { __T["+ Auto join run (continue saved)"], __T["+ Auto redeem codes"], __T["+ Auto daily reward"] } },
        { "Player", { __T["+ Third person"], __T["+ Speed + jump"], __T["+ Lobby teleports"], __T["+ Noclip"], __T["+ Anti AFK"], __T["+ Teleports"], __T["+ No screen shake"], __T["+ Block Robux prompts"] } },
        { __T["Other"], { __T["+ Streamer mode"] } },
    }
    for _, g in ipairs(groups) do
        CG:AddLabel('<b>' .. g[1] .. '</b>', true)
        for _, l in ipairs(g[2]) do CG:AddLabel(l, true) end
